entries[29671] = { ["name"] = "Armschienen der grünen Festung", ["text"] = "Wirken in 50 sek.\nTools: Schmiedehammer\nReagenzien:\nGehärteter Adamantitbarren (6), Urleben (20), Urnether\nArmschienen der grünen Festung\nWird beim Anlegen gebunden\nHandgelenke Platte\n581 Rüstung\n+39 Ausdauer\nHaltbarkeit 55 / 55\n70\nAnlegen: Erhöht die Verteidigungswertung um 17.\nAnlegen: Erhöht Eure Ausweichwertung um 10." }
entries[29672] = { ["name"] = "Gesegnete Armschienen", ["text"] = "Wirken in 50 sek.\nTools: Schmiedehammer\nReagenzien:\nGehärteter Adamantitbarren (6), Urmacht (2), Urwasser (15), Urnether\nGesegnete Armschienen\nWird beim Anlegen gebunden\nHandgelenke Platte\n581 Rüstung\n+12 Ausdauer\n+14 Intelligenz\nHaltbarkeit 55 / 55\n70\nAnlegen: Erhöht die kritische Zaubertrefferwertung um 18.\nAnlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 57 und den verursachten Schaden um bis zu 19." }
entries[29673] = { ["name"] = "Sandsack", ["text"] = "Nahkampfreichweite\nNächster Nahkampf\nVerringert bei einem Gegner 10 Sek. lang das Angriffstempo um 35% und das Bewegungstempo um 35% und fügt 3500 bis 4500 Schaden zu." }
entries[29674] = { ["name"] = "Geringe Abschirmung", ["text"] = "Sofort 1 sek. Abklingzeit\nAbsorbiert 1000 Schaden. Hält bis Abbruch lang an." }
entries[29675] = { ["name"] = "Rösten", ["text"] = "45 Meter Reichweite\nSofort\nVerbrennt einen Gegner und fügt dann zusätzlich 21 Sek. lang alle 3 Sek. Feuerschaden zu." }
entries[29676] = { ["name"] = "Nudelholz", ["text"] = "Nahkampfreichweite\nSofort\nFügt dem ausgewählten Gegner 2250 bis 2750 Schaden zu und schleudert ihn 2 Sek. lang zu Boden." }
entries[29677] = { ["name"] = "Hammerwurf", ["text"] = "5 - 30 Meter Reichweite\nWirken in 1 sek.\nWirft einen Hammer auf einen Gegner und fügt körperlichen Schaden zu." }
entries[29679] = { ["name"] = "Langweiliger Monolog", ["text"] = "30 Meter Reichweite\nWirken in 1 sek.\nVersetzt einen Feind bis zu 10 Sek. lang in Schlaf. Jeglicher erlittene Schaden führt dazu, dass das Ziel erwacht. Es kann immer nur jeweils ein Ziel in Schlaf versetzt werden." }
entries[29680] = { ["name"] = "Der letzte Vorhang", ["text"] = "Sofort\nFügt in einem Gebiet Feuerschaden zu." }
entries[29683] = { ["name"] = "Rampenlicht", ["text"] = "5 Meter Reichweite\nSofort\nBeschwört 15 Sek. lang einen Lichtkegel am Ort des Zaubernden, der jeden im Inneren stärkt." }
entries[29684] = { ["name"] = "Schildschlag", ["text"] = "Nahkampfreichweite\nSofort\nFügt einem Gegner 1850 bis 2150 Schaden zu und lähmt ihn 3 Sek. lang." }
entries[29685] = { ["name"] = "Erschreckendes Gebrüll", ["text"] = "Sofort\nLässt in der Nähe befindliche Feinde 5 Sek. lang voller Furcht flüchten." }
entries[29686] = { ["name"] = "Gehärtetes Adamantit verhütten", ["text"] = "Wirken in 3 sek.\nReagenzien:\nAdamantitbarren (10)\nErmöglicht dem Minenarbeiter, Adamantitbarren zu einem gehärteten Adamantitbarren zu verhütten. Das Verhütten von gehärtetem Adamantit erfordert eine Schmiede.\nGehärteter Adamantitbarren" }
entries[29688] = { ["name"] = "Transmutieren: Urmacht", ["text"] = "Wirken in 25 sek. 20 std. Abklingzeit\nTools: Stein der Weisen\nReagenzien:\nUrerde , Urwasser , Urluft , Urfeuer , Urmana\nTransmutiert Urerde, Urwasser, Urluft, Urfeuer und Urmana zu Urmacht.\nUrmacht" }
entries[29690] = { ["name"] = "Trunkschädelbrecher", ["text"] = "40 Meter Reichweite\nSofort\nFügt einem Gegner normalen Schaden plus 285 bis 315 zu und betäubt ihn 4 Sek. lang." }
