entries[29692] = { ["name"] = "Teufelsstahllangschwert", ["text"] = "Wirken in 50 sek.\nTools: Schmiedehammer\nReagenzien:\nKhoriumbarren (10), Teufelsstahlbarren (10), Urmacht (6), Urnether (2)\nTeufelsstahllangschwert\nWird beim Anlegen gebunden\nEinhändig Schwert\n128 - 239 Schaden Tempo 2.20\n(83.41 Schaden pro Sekunde)\n+26 Beweglichkeit\n+15 Ausdauer\nHaltbarkeit 105 / 105\n70" }
entries[29693] = { ["name"] = "Khoriumchampion", ["text"] = "Wirken in 50 sek.\nTools: Schmiedehammer\nReagenzien:\nKhoriumbarren (20), Gehärteter Adamantitbarren (2), Urmacht (6), Urnether (2)\nKhoriumchampion\nWird beim Anlegen gebunden\nZweihändig Schwert\n286 - 430 Schaden Tempo 3.30\n(108.48 Schaden pro Sekunde)\n+50 Stärke\nHaltbarkeit 120 / 120\n70\nAnlegen: Erhöht die Trefferwertung um 37.\nTrefferchance: Sich selbst um 270 bis 450 heilen und Stärke 30 Sek. lang um 120 erhöhen." }
entries[29694] = { ["name"] = "Teuflisch scharfe Kampfaxt", ["text"] = "Wirken in 50 sek.\nTools: Schmiedehammer\nReagenzien:\nKhoriumbarren (10), Teufelsstahlbarren (10), Urmacht (8), Urnether (2)\nTeuflisch scharfe Kampfaxt\nWird beim Anlegen gebunden\nEinhändig Axt\n128 - 239 Schaden Tempo 2.20\n(83.41 Schaden pro Sekunde)\n\nRoter Sockel\nSockelbonus: +3 Ausdauer\n\nHaltbarkeit 105 / 105\n70\nAnlegen: Erhöht die Trefferwertung um 14.\nAnlegen: Erhöht die kritische Trefferwertung um 21." }
entries[29695] = { ["name"] = "Teufelsstahlschneide", ["text"] = "Wirken in 50 sek.\nTools: Schmiedehammer\nReagenzien:\nKhoriumbarren (10), Teufelsstahlbarren (10), Urmacht (8), Urnether (2)\nTeufelsstahlschneide\nWird beim Anlegen gebunden\nZweihändig Axt\n295 - 443 Schaden Tempo 3.40\n(108.53 Schaden pro Sekunde)\nHaltbarkeit 120 / 120\n70\nAnlegen: Erhöht die kritische Trefferwertung um 30.\nAnlegen: Erhöht die Angriffskraft um 112." }
entries[29696] = { ["name"] = "Runenverzierter Hammer", ["text"] = "Wirken in 50 sek.\nTools: Schmiedehammer\nReagenzien:\nKhoriumbarren (10), Teufelsstahlbarren (10), Urmacht (8), Urnether (2)\nRunenverzierter Hammer\nWird beim Anlegen gebunden\nEinhändig Streitkolben\n140 - 261 Schaden Tempo 2.40\n(83.54 Schaden pro Sekunde)\n+16 Ausdauer\nHaltbarkeit 105 / 105\n70\nAnlegen: Erhöht die Angriffskraft um 50." }
entries[29697] = { ["name"] = "Teufelsgehärteter Schlägel", ["text"] = "Wirken in 50 sek.\nTools: Schmiedehammer\nReagenzien:\nKhoriumbarren (10), Teufelsstahlbarren (10), Urmacht (8), Urnether (2)\nTeufelsgehärteter Schlägel\nWird beim Anlegen gebunden\nZweihändig Streitkolben\n286 - 430 Schaden Tempo 3.30\n(108.48 Schaden pro Sekunde)\n+50 Stärke\n+46 Ausdauer\nHaltbarkeit 120 / 120\n70\nAnlegen: Erhöht die kritische Trefferwertung um 21." }
entries[29698] = { ["name"] = "Runenverzierte Eterniumklinge", ["text"] = "Wirken in 50 sek.\nTools: Schmiedehammer\nReagenzien:\nKhoriumbarren (10), Gehärteter Adamantitbarren (4), Eterniumbarren (10), Urmacht (8), Urnether (2)\nRunenverzierte Eterniumklinge\nWird beim Anlegen gebunden\nWaffenhand Dolch\n28 - 114 Schaden Tempo 1.70\n(41.76 Schaden pro Sekunde)\n+19 Intelligenz\nHaltbarkeit 75 / 75\n70\nAnlegen: Erhöht die kritische Zaubertrefferwertung um 21.\nAnlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 168." }
entries[29699] = { ["name"] = "Todeslied", ["text"] = "Wirken in 50 sek.\nTools: Schmiedehammer\nReagenzien:\nKhoriumbarren (10), Teufelsstahlbarren (10), Urmacht (8), Urnether (2)\nTodeslied\nWird beim Anlegen gebunden\nEinhändig Dolch\n81 - 152 Schaden Tempo 1.40\n(83.21 Schaden pro Sekunde)\nHaltbarkeit 75 / 75\n70\nAnlegen: Erhöht die kritische Trefferwertung um 20.\nAnlegen: Erhöht die Angriffskraft um 40." }
entries[29700] = { ["name"] = "Hand der Ewigkeit", ["text"] = "Wirken in 50 sek.\nTools: Schmiedehammer\nReagenzien:\nKhoriumbarren (10), Gehärteter Adamantitbarren (4), Eterniumbarren (10), Urmacht (8), Urnether (4)\nHand der Ewigkeit\nWird beim Anlegen gebunden\nWaffenhand Streitkolben\n35 - 131 Schaden Tempo 1.90\n(43.68 Schaden pro Sekunde)\n+20 Intelligenz\nHaltbarkeit 105 / 105\n70\nAnlegen: Stellt alle 5 Sek. 7 Mana wieder her.\nAnlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 317 und den verursachten Schaden um bis zu 106." }
