entries[29848] = { ["name"] = "Verwandlung", ["text"] = "30 Meter Reichweite\nSofort\nVerwandelt den Feind in ein Schaf und zwingt ihn, 20 Sek. lang so herumzuwandern. Während das Schaf herumwandert, kann es weder angreifen noch Zauber wirken. Jeglicher erlittene Schaden verwandelt das Ziel in seine normale Gestalt zurück. Es kann immer nur jeweils ein Ziel verwandelt werden. Wirkt nur bei Wildtieren, Drachen, Riesen, Humanoiden und Tieren." }
