entries[30349] = { ["name"] = "Werkzeugkasten aus Khorium", ["text"] = "Wirken in 45 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nTeufelseisengehäuse , Khoriumbarren (5), Eine Hand voll Teufelseisenbolzen (2)\nWerkzeugkasten aus Khorium\nWird beim Anlegen gebunden\n28 Platz Ingenieurstasche\n\"Unterteilt in kleine Fächer, die sich perfekt für die Aufbewahrung von Ingenieursbedarf eignen.\"" }
entries[30350] = { ["name"] = "Ingenieurskunst", ["text"] = "Sofort\nErmöglicht einem Ingenieur, Bomben und Dinge, die fast immer funktionieren, mit einer maximalen potenziellen Fertigkeit von 375 herzustellen." }
