entries[30404] = { ["name"] = "Instabiles Gebrechen", ["text"] = "330 Mana 30 Meter Reichweite\nWirken in 1.5 sek.\nSchattenenergie zerstört langsam das Ziel, indem 18 Sek. lang insgesamt 840 Schaden zugefügt werden. Sollte 'Instabiles Gebrechen' gebannt werden, verursacht es 1260 Schaden beim Bannenden und bringt diesen 5 Sek. lang zum Schweigen." }
